CREATE COLUMN TABLE "TEST_AP"."FRC1" ("CatId" SMALLINT CS_INT NOT NULL , "TemplateId" INTEGER CS_INT NOT NULL , "AcctCode" NVARCHAR(15) NOT NULL , "VisOrder" SMALLINT CS_INT NOT NULL , "CFWId" INTEGER CS_INT, "CalcMethod" NVARCHAR(30), "SlpCode" INTEGER CS_INT, "PrcCode" NVARCHAR(8), "CalMethod2" NVARCHAR(30), "CalMethod3" NVARCHAR(30), "Linked" NVARCHAR(1) DEFAULT 'B', "Sign" NVARCHAR(1) DEFAULT 'E', PRIMARY KEY ("TemplateId", "CatId", "AcctCode", "VisOrder")) UNLOAD PRIORITY 5  AUTO MERGE ;
